{
    "level": "B2",
    "intro": "У цій темі ти детально вивчиш <strong>Future Continuous Passive<\/strong> (Майбутній тривалий пасив). <strong>Важливо:<\/strong> ця форма використовується дуже рідко в реальному спілкуванні через незручну конструкцію.",
    "rules": [
        {
            "label": "Формула",
            "color": "emerald",
            "text": "<strong>Subject + will be being + V3<\/strong>:",
            "example": "The house will be being painted at this time tomorrow."
        },
        {
            "label": "Заперечення",
            "color": "rose",
            "text": "<strong>Subject + will not be being + V3<\/strong>:",
            "example": "The report will not be being written at that moment."
        },
        {
            "label": "⚠️ Увага",
            "color": "amber",
            "text": "Ця форма <strong>майже не використовується<\/strong>!",
            "example": "Краще: The house will be painted tomorrow."
        }
    ]
}

{
    "title": "1. Структура Future Continuous Passive",
    "intro": "Формула: <strong>will + be + being + V3<\/strong>. Ця структура незручна, тому рідко вживається:",
    "items": [
        {
            "label": "Всі особи",
            "title": "will be being + V3",
            "subtitle": "I\/You\/He\/She\/It\/We\/They will be being interviewed."
        },
        {
            "label": "Singular",
            "title": "will be being + V3",
            "subtitle": "The car will be being repaired. — Машину будуть ремонтувати."
        },
        {
            "label": "Plural",
            "title": "will be being + V3",
            "subtitle": "The documents will be being processed. — Документи будуть обробляти."
        },
        {
            "label": "⚠️ Рідко!",
            "title": "Краще уникати",
            "subtitle": "Зазвичай замінюють на Future Simple Passive."
        }
    ]
}

{
    "title": "2. Стверджувальні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "emerald",
            "description": "Порядок слів: <strong>Subject + will be being + V3<\/strong>",
            "examples": [
                {
                    "en": "The house will be being painted at this time tomorrow.",
                    "ua": "Будинок будуть фарбувати в цей час завтра."
                },
                {
                    "en": "The project will be being discussed at 3 PM.",
                    "ua": "Проєкт будуть обговорювати о 15:00."
                },
                {
                    "en": "The documents will be being reviewed all day.",
                    "ua": "Документи будуть переглядати весь день."
                }
            ]
        },
        {
            "label": "⚠️ Практична порада",
            "color": "amber",
            "description": "<strong>Краще використовувати Future Simple Passive або активний стан<\/strong>:",
            "examples": [
                {
                    "en": "Instead: The house will be painted tomorrow.",
                    "ua": "Краще: Будинок пофарбують завтра."
                },
                {
                    "en": "Or active: They will be painting the house.",
                    "ua": "Або активний: Вони будуть фарбувати будинок."
                }
            ]
        }
    ]
}

{
    "title": "3. Коли (теоретично) використовувати Future Continuous Passive?",
    "sections": [
        {
            "label": "Тривала дія в момент майбутнього",
            "color": "emerald",
            "description": "Для підкреслення, що дія <strong>триватиме в певний момент<\/strong>:",
            "examples": [
                {
                    "en": "At 10 AM tomorrow, the meeting will be being held.",
                    "ua": "Завтра о 10 ранку буде проводитися зустріч."
                },
                {
                    "en": "This time next week, the building will be being renovated.",
                    "ua": "В цей час наступного тижня будівлю будуть ремонтувати."
                }
            ]
        },
        {
            "label": "Чому уникають цю форму?",
            "color": "rose",
            "description": "Причини, чому ця форма <strong>рідко використовується<\/strong>:",
            "examples": [
                {
                    "en": "Too awkward: \"will be being\" sounds clumsy.",
                    "ua": "Занадто незручно: \"will be being\" звучить незграбно."
                },
                {
                    "en": "Confusing: Three verb forms in a row (be being done).",
                    "ua": "Заплутано: Три форми дієслова поспіль."
                },
                {
                    "en": "Easier alternatives exist.",
                    "ua": "Існують простіші альтернативи."
                }
            ]
        }
    ]
}

{
    "title": "4. Заперечні речення",
    "sections": [
        {
            "label": "Структура",
            "color": "rose",
            "description": "Додаємо <strong>not<\/strong> після will: <strong>Subject + will not be being + V3<\/strong>",
            "examples": [
                {
                    "en": "The report will not be being written at that moment.",
                    "ua": "Звіт не будуть писати в той момент."
                },
                {
                    "en": "The car will not be being repaired tomorrow afternoon.",
                    "ua": "Машину не будуть ремонтувати завтра вдень."
                }
            ]
        },
        {
            "label": "Скорочена форма",
            "color": "amber",
            "description": "У розмовній мові: <strong>won't be being<\/strong> (ще більш незвично)",
            "examples": [
                {
                    "en": "The documents won't be being processed then.",
                    "ua": "Документи не будуть обробляти тоді."
                }
            ]
        }
    ]
}

{
    "title": "5. Питальні речення",
    "sections": [
        {
            "label": "Yes\/No питання",
            "color": "blue",
            "description": "<strong>Will + Subject + be being + V3?<\/strong>",
            "examples": [
                {
                    "en": "Will the house be being painted at that time?",
                    "ua": "Будинок будуть фарбувати в той час?"
                },
                {
                    "en": "Will the project be being discussed tomorrow?",
                    "ua": "Проєкт будуть обговорювати завтра?"
                }
            ]
        },
        {
            "label": "Wh-питання",
            "color": "sky",
            "description": "<strong>Wh-word + will + Subject + be being + V3?<\/strong>",
            "examples": [
                {
                    "en": "What will be being done at 5 PM?",
                    "ua": "Що будуть робити о 17:00?"
                },
                {
                    "en": "Where will the meeting be being held?",
                    "ua": "Де буде проводитися зустріч?"
                }
            ]
        }
    ]
}

{
    "title": "6. Кращі альтернативи",
    "intro": "Замість Future Continuous Passive краще використовувати:",
    "rows": [
        {
            "en": "❌ The house will be being painted.",
            "ua": "(незграбно)",
            "note": "✅ The house will be painted. (Future Simple Passive)"
        },
        {
            "en": "❌ The report will be being written.",
            "ua": "(занадто складно)",
            "note": "✅ They will be writing the report. (Future Continuous Active)"
        },
        {
            "en": "❌ The car will be being repaired.",
            "ua": "(важко вимовити)",
            "note": "✅ The car will be repaired. \/ The car is going to be repaired."
        }
    ],
    "warning": "📌 У 99% випадків краще використовувати Future Simple Passive або Future Continuous Active!"
}

{
    "title": "7. Active vs Passive у Future Continuous",
    "intro": "Порівняння активного та пасивного стану:",
    "rows": [
        {
            "en": "Active: They will be painting the house.",
            "ua": "Вони будуть фарбувати будинок.",
            "note": "→ Passive: The house will be being painted. (рідко)"
        },
        {
            "en": "Active: We will be discussing the project.",
            "ua": "Ми будемо обговорювати проєкт.",
            "note": "→ Passive: The project will be being discussed. (рідко)"
        },
        {
            "en": "Active: Someone will be repairing the car.",
            "ua": "Хтось буде ремонтувати машину.",
            "note": "→ Passive: The car will be being repaired. (рідко)"
        }
    ],
    "warning": "📌 Активний стан Future Continuous звучить набагато природніше!"
}

{
    "title": "8. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск being.",
            "wrong": "The house will be painted now. (якщо потрібен Continuous)",
            "right": "✅ The house will be being painted now. (або краще: is being painted)"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Неправильний порядок.",
            "wrong": "The report will being be written.",
            "right": "✅ The report will be being written."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання been замість being.",
            "wrong": "The car will be been repaired.",
            "right": "✅ The car will be being repaired."
        },
        {
            "label": "Порада",
            "color": "emerald",
            "title": "Краща стратегія.",
            "wrong": "Намагатися використовувати Future Continuous Passive.",
            "right": "✅ Використовувати Future Simple Passive або Active."
        }
    ]
}

{
    "title": "Passive in Tenses",
    "items": [
        {
            "label": "Present Simple Passive — Теперішній простий пасив",
            "current": false
        },
        {
            "label": "Present Continuous Passive — Теперішній тривалий пасив",
            "current": false
        },
        {
            "label": "Present Perfect Passive — Теперішній доконаний пасив",
            "current": false
        },
        {
            "label": "Past Simple Passive — Минулий простий пасив",
            "current": false
        },
        {
            "label": "Past Continuous Passive — Минулий тривалий пасив",
            "current": false
        },
        {
            "label": "Past Perfect Passive — Минулий доконаний пасив",
            "current": false
        },
        {
            "label": "Future Simple Passive — Майбутній простий пасив",
            "current": false
        },
        {
            "label": "Future Continuous Passive — Майбутній тривалий пасив",
            "current": true
        },
        {
            "label": "Future Perfect Passive — Майбутній доконаний пасив",
            "current": false
        }
    ]
}

{
    "level": "B1",
    "intro": "У цій темі ти дізнаєшся, <strong>коли додавати \"by + agent\"<\/strong> у пасивних реченнях, коли його краще опустити, та яка різниця між <strong>by<\/strong> та <strong>with<\/strong>.",
    "rules": [
        {
            "label": "Додавай by",
            "color": "emerald",
            "text": "Коли виконавець <strong>важливий або новий<\/strong>:",
            "example": "The book was written by J.K. Rowling."
        },
        {
            "label": "Опускай by",
            "color": "blue",
            "text": "Коли виконавець <strong>очевидний або невідомий<\/strong>:",
            "example": "He was arrested. (поліцією — очевидно)"
        },
        {
            "label": "by vs with",
            "color": "rose",
            "text": "<strong>by<\/strong> — виконавець, <strong>with<\/strong> — інструмент:",
            "example": "The letter was written by Tom with a pen."
        }
    ]
}

{
    "title": "1. Коли ДОДАВАТИ \"by + agent\"",
    "sections": [
        {
            "label": "Виконавець важливий",
            "color": "emerald",
            "description": "Якщо виконавець — <strong>ключова інформація<\/strong>, його потрібно вказати.",
            "examples": [
                {
                    "en": "The Mona Lisa was painted by Leonardo da Vinci.",
                    "ua": "«Мона Ліза» була намальована Леонардо да Вінчі."
                },
                {
                    "en": "This song was performed by Adele.",
                    "ua": "Ця пісня була виконана Адель."
                },
                {
                    "en": "The company was founded by Steve Jobs.",
                    "ua": "Компанію заснував Стів Джобс."
                }
            ]
        },
        {
            "label": "Нова інформація",
            "color": "sky",
            "description": "Коли виконавець — <strong>нова, несподівана інформація<\/strong> для слухача.",
            "examples": [
                {
                    "en": "I was helped by a stranger.",
                    "ua": "Мені допоміг незнайомець."
                },
                {
                    "en": "The window was broken by the kids next door.",
                    "ua": "Вікно розбили сусідські діти."
                },
                {
                    "en": "The project was completed by our junior team.",
                    "ua": "Проєкт завершила наша молодша команда."
                }
            ]
        },
        {
            "label": "Контраст \/ акцент",
            "color": "amber",
            "description": "Коли хочемо <strong>підкреслити, хто саме<\/strong> виконав дію.",
            "examples": [
                {
                    "en": "The report was written by me, not by Tom.",
                    "ua": "Звіт написав я, а не Том."
                },
                {
                    "en": "The cake was made by my grandmother.",
                    "ua": "Торт спекла моя бабуся. (акцент)"
                }
            ]
        }
    ]
}

{
    "title": "2. Коли ОПУСКАТИ \"by + agent\"",
    "sections": [
        {
            "label": "Виконавець очевидний",
            "color": "emerald",
            "description": "Коли з контексту <strong>зрозуміло<\/strong>, хто виконує дію.",
            "examples": [
                {
                    "en": "He was arrested.",
                    "ua": "Його заарештували. (поліція — очевидно)"
                },
                {
                    "en": "The patient was operated on.",
                    "ua": "Пацієнта прооперували. (лікарі — очевидно)"
                },
                {
                    "en": "The letter was delivered.",
                    "ua": "Листа доставили. (пошта — очевидно)"
                }
            ]
        },
        {
            "label": "Виконавець невідомий",
            "color": "sky",
            "description": "Ми <strong>не знаємо<\/strong>, хто виконав дію.",
            "examples": [
                {
                    "en": "My car was stolen.",
                    "ua": "Мою машину вкрали. (хто — невідомо)"
                },
                {
                    "en": "The building was constructed in 1920.",
                    "ua": "Будівлю зведено в 1920 році."
                },
                {
                    "en": "The window was broken last night.",
                    "ua": "Вікно розбили вчора ввечері."
                }
            ]
        },
        {
            "label": "Виконавець неважливий",
            "color": "amber",
            "description": "Нам <strong>байдуже<\/strong>, хто виконує дію. Важливий результат.",
            "examples": [
                {
                    "en": "English is spoken here.",
                    "ua": "Тут розмовляють англійською."
                },
                {
                    "en": "The rules must be followed.",
                    "ua": "Правила треба дотримуватися."
                },
                {
                    "en": "The work will be finished tomorrow.",
                    "ua": "Робота буде закінчена завтра."
                }
            ]
        },
        {
            "label": "Загальний виконавець",
            "color": "rose",
            "description": "Коли виконавець — <strong>люди загалом<\/strong>: people, someone, they.",
            "examples": [
                {
                    "en": "It is believed that... (people believe)",
                    "ua": "Вважається, що... (люди вважають)"
                },
                {
                    "en": "The meeting was cancelled.",
                    "ua": "Зустріч скасували. (хтось)"
                }
            ]
        }
    ]
}

{
    "title": "3. \"by\" vs \"with\" — виконавець vs інструмент",
    "sections": [
        {
            "label": "by — виконавець",
            "color": "emerald",
            "description": "<strong>by<\/strong> вказує на <strong>того, хто виконує<\/strong> дію (людина, організація, сила).",
            "examples": [
                {
                    "en": "The letter was written by Tom.",
                    "ua": "Лист написав Том. (виконавець)"
                },
                {
                    "en": "The house was destroyed by the earthquake.",
                    "ua": "Будинок зруйнувало землетрусом. (сила)"
                },
                {
                    "en": "The decision was made by the committee.",
                    "ua": "Рішення ухвалив комітет. (організація)"
                }
            ]
        },
        {
            "label": "with — інструмент",
            "color": "blue",
            "description": "<strong>with<\/strong> вказує на <strong>інструмент або засіб<\/strong>, яким виконано дію.",
            "examples": [
                {
                    "en": "The letter was written with a pen.",
                    "ua": "Лист написано ручкою. (інструмент)"
                },
                {
                    "en": "The cake was decorated with cream.",
                    "ua": "Торт прикрашено кремом. (матеріал)"
                },
                {
                    "en": "The door was locked with a key.",
                    "ua": "Двері замкнуто ключем."
                }
            ]
        },
        {
            "label": "Поєднання by + with",
            "color": "amber",
            "description": "Можна використати <strong>обидва<\/strong> в одному реченні.",
            "examples": [
                {
                    "en": "The picture was painted by Monet with oil paints.",
                    "ua": "Картину намалював Моне олійними фарбами."
                },
                {
                    "en": "The document was signed by the manager with a fountain pen.",
                    "ua": "Документ підписав менеджер перовою ручкою."
                }
            ]
        }
    ]
}

{
    "title": "4. Порівняння: by vs with",
    "intro": "Ключова різниця між by та with у пасивних реченнях:",
    "rows": [
        {
            "en": "by + agent",
            "ua": "Виконавець дії",
            "note": "The book was written by J.K. Rowling."
        },
        {
            "en": "with + instrument",
            "ua": "Інструмент, засіб",
            "note": "The book was written with a pencil."
        },
        {
            "en": "by + natural force",
            "ua": "Природна сила",
            "note": "The tree was struck by lightning."
        },
        {
            "en": "with + material",
            "ua": "Матеріал",
            "note": "The house was built with bricks."
        }
    ],
    "warning": "📌 <strong>by<\/strong> = хто\/що спричинило дію. <strong>with<\/strong> = чим виконано дію."
}

{
    "title": "5. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Зайвий \"by\" з очевидним виконавцем.",
            "wrong": "He was arrested by police.",
            "right": "✅ He was arrested. (поліція очевидна)"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Плутанина by та with.",
            "wrong": "The letter was written with Tom.",
            "right": "✅ The letter was written by Tom."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Використання by замість with для інструменту.",
            "wrong": "The cake was cut by a knife.",
            "right": "✅ The cake was cut with a knife."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Додавання \"by someone\/people\" без потреби.",
            "wrong": "English is spoken by people here.",
            "right": "✅ English is spoken here."
        }
    ]
}

{
    "title": "Passive Special Cases",
    "items": [
        {
            "label": "By-phrase — by + agent у пасиві",
            "current": true
        }
    ]
}
